</div>

@code {
    [Parameter, EditorRequired]
    public List<Product> Products { get; set; } = [];

    [Parameter]
    public EventCallback<Product> OnProductSelected { get; set; }

    [Parameter]
    public EventCallback<Product> OnAddToCart { get; set; }
}

@using sv_0edb3f35f7344982b1b1997c64ab06d3.Services

<aside class="catalog-sidebar">
    <h2>Filters</h2>

    <div class="filter-section">
        <h3>Category</h3>
        @foreach (var category in Categories)
        {
            <label class="filter-checkbox">
                <input type="checkbox"
                       checked="@IsSelected(category)"
                       @onchange="() => ToggleCategory(category)" />
                @category
            </label>
        }
    </div>

    <div class="filter-section">
        <h3>Price Range</h3>
        <div class="price-inputs">
            <label>
                Min
                <input type="number" min="0" step="0.01"
                       value="@_minPrice"
                       @onchange="e => _minPrice = ParseDecimal(e.Value)" />
            </label>
            <label>
                Max
                <input type="number" min="0" step="0.01"
                       value="@_maxPrice"
                       @onchange="e => _maxPrice = ParseDecimal(e.Value)" />
            </label>
        </div>
    </div>

    <div class="filter-section">
        <label class="filter-checkbox">
            <input type="checkbox" @bind="_inStockOnly" />
            In Stock Only
        </label>
    </div>

    <div class="filter-actions">
        <button class="btn-apply" @onclick="ApplyFilters">Apply Filters</button>
        <button class="btn-clear" @onclick="ClearFilters">Clear Filters</button>
    </div>
</aside>

@code {
    [Parameter, EditorRequired]
    public List<string> Categories { get; set; } = [];

    [Parameter]
    public EventCallback<ProductFilter> OnFilterApplied { get; set; }

    [Parameter]
    public EventCallback OnFilterCleared { get; set; }

    private HashSet<string> _selectedCategories = new();
    private decimal? _minPrice;
    private decimal? _maxPrice;
    private bool _inStockOnly;

    private bool IsSelected(string category) => _selectedCategories.Contains(category);

    private void ToggleCategory(string category)
    {
        if (!_selectedCategories.Remove(category))
        {
            _selectedCategories.Add(category);
        }
    }

    private async Task ApplyFilters()
    {
        var filter = new ProductFilter(
            Categories: _selectedCategories.Count > 0 ? _selectedCategories.ToList() : null,
            MinPrice: _minPrice,
            MaxPrice: _maxPrice,
            InStockOnly: _inStockOnly
        );
        await OnFilterApplied.InvokeAsync(filter);
    }

    private async Task ClearFilters()
    {
        _selectedCategories.Clear();
        _minPrice = null;
        _maxPrice = null;
        _inStockOnly = false;
        await OnFilterCleared.InvokeAsync();
    }

    private static decimal? ParseDecimal(object? value)
    {
        if (value is null || string.IsNullOrWhiteSpace(value.ToString()))
            return null;
        return decimal.TryParse(value.ToString(), out var result) ? result : null;
    }
}

@page "/catalog"
@using sv_0edb3f35f7344982b1b1997c64ab06d3.Services
@inject IProductService ProductService
@rendermode InteractiveServer

<PageTitle>Product Catalog</PageTitle>

<h1>Product Catalog</h1>

<div class="catalog-layout">
    <CatalogSidebar Categories="_categories"
                    OnFilterApplied="HandleFilterApplied"
                    OnFilterCleared="HandleFilterCleared" />

    <main class="catalog-main">
        @if (_loading)
        {
            <div class="catalog-status">Loading products…</div>
        }
        else if (_error is not null)
        {
            <div class="catalog-status catalog-error">
                <p>Something went wrong: @_error</p>
                <button class="btn-apply" @onclick="LoadProductsAsync">Retry</button>
            </div>
        }
        else if (_result is null || _result.Items.Count == 0)
        {
            <div class="catalog-status">No products found. Try adjusting your filters.</div>
        }
        else
        {
            <CatalogToolbar SortBy="@_sortBy"
                            TotalCount="_result.TotalCount"
                            Page="_result.Page"
                            PageSize="_result.PageSize"
                            OnSortChanged="HandleSortChanged" />

            <ProductGrid Products="_result.Items"
                         OnProductSelected="HandleProductSelected"
                         OnAddToCart="HandleAddToCart" />

            <CatalogPagination CurrentPage="_currentPage"
                               TotalPages="_totalPages"
                               OnPageChanged="HandlePageChanged" />
        }
    </main>
</div>

@code {
    private List<string> _categories = [];
    private PagedResult<Product>? _result;
    private ProductFilter _filter = new(null, null, null, false);
    private string _sortBy = "price_asc";
    private int _currentPage = 1;
    private const int PageSize = 12;
    private bool _loading;
    private string? _error;

    private int _totalPages => _result is null || _result.TotalCount == 0
        ? 1
        : (int)Math.Ceiling((double)_result.TotalCount / _result.PageSize);

    protected override async Task OnInitializedAsync()
    {
        await LoadCategoriesAsync();
        await LoadProductsAsync();
    }

    private async Task LoadCategoriesAsync()
    {
        try
        {
            _categories = await ProductService.GetCategoriesAsync();
        }
        catch
        {
            _categories = [];
        }
    }

    private async Task LoadProductsAsync()
    {
        _loading = true;
        _error = null;

        try
        {
            _result = await ProductService.SearchAsync(_filter, _sortBy, _currentPage, PageSize);
        }
        catch (Exception ex)
        {
            _error = ex.Message;
            _result = null;
        }
        finally
        {
            _loading = false;
        }
    }

    private async Task HandleFilterApplied(ProductFilter filter)
    {
        _filter = filter;
        _currentPage = 1;
        await LoadProductsAsync();
    }

    private async Task HandleFilterCleared()
    {
        _filter = new ProductFilter(null, null, null, false);
        _currentPage = 1;
        await LoadProductsAsync();
    }

    private async Task HandleSortChanged(string sortBy)
    {
        _sortBy = sortBy;
        _currentPage = 1;
        await LoadProductsAsync();
    }

    private async Task HandlePageChanged(int page)
    {
        _currentPage = page;
        await LoadProductsAsync();
    }

    private Task HandleProductSelected(Product product)
    {
        // Parent page handles navigation to detail page
        return OnProductSelected.InvokeAsync(product);
    }

    private Task HandleAddToCart(Product product)
    {
        return OnAddToCart.InvokeAsync(product);
    }

    /// <summary>
    /// Raised when a product card is clicked so a parent component can navigate to the detail page.
    /// </summary>
    [Parameter]
    public EventCallback<Product> OnProductSelected { get; set; }

    [Parameter]
    public EventCallback<Product> OnAddToCart { get; set; }
}

.catalog-layout {
    display: flex;
    gap: 1.5rem;
}

/* Sidebar */
::deep .catalog-sidebar {
    flex: 0 0 25%;
    max-width: 25%;
    padding: 1rem;
    border-right: 1px solid #e0e0e0;
}

::deep .catalog-sidebar h2 {
    margin-top: 0;
    font-size: 1.25rem;
}

::deep .catalog-sidebar h3 {
    font-size: 1rem;
    margin: 1rem 0 0.5rem;
}

::deep .filter-section {
    margin-bottom: 1rem;
}

::deep .filter-checkbox {
    display: flex;
    align-items: center;
    gap: 0.4rem;
    margin-bottom: 0.35rem;
    cursor: pointer;
}

::deep .price-inputs {
    display: flex;
    gap: 0.75rem;
}

::deep .price-inputs label {
    display: flex;
    flex-direction: column;
    font-size: 0.85rem;
}

::deep .price-inputs input {
    width: 90px;
    padding: 0.3rem;
    margin-top: 0.2rem;
}

::deep .filter-actions {
    display: flex;
    gap: 0.5rem;
    margin-top: 1rem;
}

::deep .btn-apply,
::deep .btn-clear {
    padding: 0.45rem 1rem;
    border: none;
    border-radius: 4px;
    cursor: pointer;
    font-size: 0.9rem;
}

::deep .btn-apply {
    background: #0d6efd;
    color: #fff;
}

::deep .btn-apply:hover {
    background: #0b5ed7;
}

::deep .btn-clear {
    background: #6c757d;
    color: #fff;
}

::deep .btn-clear:hover {
    background: #5a6268;
}

/* Main area */
.catalog-main {
    flex: 1;
    min-width: 0;
}

.catalog-status {
    text-align: center;
    padding: 3rem 1rem;
    color: #666;
    font-size: 1.1rem;
}

.catalog-error {
    color: #dc3545;
}

/* Toolbar */
::deep .catalog-toolbar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 1rem;
    padding: 0.5rem 0;
    border-bottom: 1px solid #e0e0e0;
}

::deep .sort-control {
    display: flex;
    align-items: center;
    gap: 0.5rem;
}

::deep .sort-control select {
    padding: 0.35rem 0.5rem;
    border: 1px solid #ccc;
    border-radius: 4px;
}

::deep .results-summary {
    color: #666;
    font-size: 0.9rem;
}

/* Product grid */
::deep .product-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));
    gap: 1.25rem;
}

::deep .product-card {
    border: 1px solid #e0e0e0;
    border-radius: 8px;
    overflow: hidden;
    cursor: pointer;
    transition: box-shadow 0.2s;
}

::deep .product-card:hover {
    box-shadow: 0 2px 12px rgba(0, 0, 0, 0.12);
}

::deep .product-image {
    background: #f0f0f0;
    height: 160px;
    display: flex;
    align-items: center;
    justify-content: center;
    color: #999;
    font-size: 0.9rem;
}

::deep .product-info {
    padding: 0.75rem;
}

::deep .product-name {
    margin: 0 0 0.4rem;
    font-size: 1rem;
}

::deep .product-price {
    margin: 0 0 0.3rem;
    font-weight: 600;
    color: #2d8a4e;
}

::deep .product-rating {
    color: #f5a623;
    font-size: 1.1rem;
    margin-bottom: 0.4rem;
}

::deep .badge-out-of-stock {
    display: inline-block;
    background: #dc3545;
    color: #fff;
    font-size: 0.75rem;
    padding: 0.15rem 0.5rem;
    border-radius: 4px;
    margin-bottom: 0.4rem;
}

::deep .btn-add-to-cart {
    width: 100%;
    padding: 0.45rem;
    border: none;
    border-radius: 4px;
    background: #0d6efd;
    color: #fff;
    cursor: pointer;
    font-size: 0.9rem;
}

::deep .btn-add-to-cart:hover:not(:disabled) {
    background: #0b5ed7;
}

::deep .btn-add-to-cart:disabled {
    background: #ccc;
    cursor: not-allowed;
}

/* Pagination */
::deep .catalog-pagination {
    display: flex;
    justify-content: center;
    gap: 0.35rem;
    margin-top: 1.5rem;
    padding-top: 1rem;
    border-top: 1px solid #e0e0e0;
}

::deep .btn-page {
    padding: 0.4rem 0.75rem;
    border: 1px solid #ccc;
    border-radius: 4px;
    background: #fff;
    cursor: pointer;
    font-size: 0.9rem;
}

::deep .btn-page:hover:not(:disabled) {
    background: #e9ecef;
}

::deep .btn-page.active {
    background: #0d6efd;
    color: #fff;
    border-color: #0d6efd;
}

::deep .btn-page:disabled {
    opacity: 0.5;
    cursor: not-allowed;
}

