    border-right: 1px solid #e0e0e0;
}

::deep .catalog-sidebar h2 {
    margin-top: 0;
    font-size: 1.25rem;
}

::deep .catalog-sidebar h3 {
    font-size: 1rem;
    margin: 1rem 0 0.5rem;
}

::deep .filter-section {
    margin-bottom: 1rem;
}

::deep .filter-checkbox {
    display: flex;
    align-items: center;
    gap: 0.4rem;
    margin-bottom: 0.35rem;
    cursor: pointer;
}

::deep .price-inputs {
    display: flex;
    gap: 0.75rem;
}

::deep .price-inputs label {
    display: flex;
    flex-direction: column;
    font-size: 0.85rem;
}

::deep .price-inputs input {
