toolArgs.file_text:
.catalog-layout {
    display: flex;
    gap: 1.5rem;
}

/* Sidebar */
::deep .catalog-sidebar {
    flex: 0 0 25%;
    max-width: 25%;
    padding: 1rem;
    border-right: 1px solid #e0e0e0;
}

::deep .catalog-sidebar h2 {
    margin-top: 0;
    font-size: 1.25rem;
}

::deep .catalog-sidebar h3 {
    font-size: 1rem;
    margin: 1rem 0 0.5rem;
}

::deep .filter-section {
    margin-bottom: 1rem;
}

::deep .filter-checkbox {
    display: flex;
    align-items: center;
    gap: 0.4rem;
    margin-bottom: 0.35rem;
    cursor: pointer;
}

::deep .price-inputs {
    display: flex;
    gap: 0.75rem;
}

::deep .price-inputs label {
    display: flex;
    flex-direction: column;
    font-size: 0.85rem;
}

::deep .price-inputs input {
    width: 90px;
    padding: 0.3rem;
    margin-top: 0.2rem;
}

::deep .filter-actions {
    display: flex;
    gap: 0.5rem;
    margin-top: 1rem;
}

::deep .btn-apply,
::deep .btn-clear {
    padding: 0.45rem 1rem;
    border: none;
    border-radius: 4px;
    cursor: pointer;
    font-size: 0.9rem;
}

::deep .btn-apply {
    background: #0d6efd;
    color: #fff;
}

::deep .btn-apply:hover {
    background: #0b5ed7;
}

::deep .btn-clear {
    background: #6c757d;
    color: #fff;
}

::deep .btn-clear:hover {
    background: #5a6268;
}

/* Main area */
.catalog-main {
    flex: 1;
    min-width: 0;
}

.catalog-status {
    text-align: center;
    padding: 3rem 1rem;
    color: #666;
    font-size: 1.1rem;
}

.catalog-error {
    color: #dc3545;
}

/* Toolbar */
::deep .catalog-toolbar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 1rem;
    padding: 0.5rem 0;
    border-bottom: 1px solid #e0e0e0;
}

::deep .sort-control {
    display: flex;
    align-items: center;
    gap: 0.5rem;
}

::deep .sort-control select {
    padding: 0.35rem 0.5rem;
    border: 1px solid #ccc;
    border-radius: 4px;
}

::deep .results-summary {
    color: #666;
    font-size: 0.9rem;
}

/* Product grid */
::deep .product-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));
    gap: 1.25rem;
}

::deep .product-card {
    border: 1px solid #e0e0e0;
    border-radius: 8px;
    overflow: hidden;
    cursor: pointer;
    transition: box-shadow 0.2s;
}

::deep .product-card:hover {
    box-shadow: 0 2px 12px rgba(0, 0, 0, 0.12);
}

::deep .product-image {
    background: #f0f0f0;
    height: 160px;
    display: flex;
    align-items: center;
    justify-content: center;
    color: #999;
    font-size: 0.9rem;
}

::deep .product-info {
    padding: 0.75rem;
}

::deep .product-name {
    margin: 0 0 0.4rem;
    font-size: 1rem;
}

::deep .product-price {
    margin: 0 0 0.3rem;
    font-weight: 600;
    color: #2d8a4e;
}

::deep .product-rating {
    color: #f5a623;
    font-size: 1.1rem;
    margin-bottom: 0.4rem;
}

::deep .badge-out-of-stock {
    display: inline-block;
    background: #dc3545;
    color: #fff;
    font-size: 0.75rem;
    padding: 0.15rem 0.5rem;
    border-radius: 4px;
    margin-bottom: 0.4rem;
}

::deep .btn-add-to-cart {
    width: 100%;
    padding: 0.45rem;
    border: none;
    border-radius: 4px;
    background: #0d6efd;
    color: #fff;
    cursor: pointer;
    font-size: 0.9rem;
}

::deep .btn-add-to-cart:hover:not(:disabled) {
    background: #0b5ed7;
}

::deep .btn-add-to-cart:disabled {
    background: #ccc;
    cursor: not-allowed;
}

/* Pagination */
::deep .catalog-pagination {
    display: flex;
    justify-content: center;
    gap: 0.35rem;
    margin-top: 1.5rem;
    padding-top: 1rem;
    border-top: 1px solid #e0e0e0;
}

::deep .btn-page {
    padding: 0.4rem 0.75rem;
    border: 1px solid #ccc;
    border-radius: 4px;
    background: #fff;
    cursor: pointer;
    font-size: 0.9rem;
}

::deep .btn-page:hover:not(:disabled) {
    background: #e9ecef;
}

::deep .btn-page.active {
    background: #0d6efd;
    color: #fff;
    border-color: #0d6efd;
}

::deep .btn-page:disabled {
    opacity: 0.5;
    cursor: not-allowed;
}

